            aOrbiterK = (aOrbiterK + aOrbiterD) + 0x12DA8479C8DCB8B5ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterK) ^ 0x7EDBCC6CD2CA1BB4ULL;
