            aOrbiterE = RotL64((aOrbiterE * 0xD9F7C73AE74CEBD5ULL), 53U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterH) + 0x84E4B57BEC6F7986ULL) + aOUSaltB[(((511U - aIndex) + 480U)) & S_SALT1];
