            //
            aOrbiterA = (((aWandererG + RotL64(aCross, 41U)) + RotL64(aCarry, 11U)) + 0xAF5872ABA8695E27ULL) + aOASaltA[(((511U - aIndex) + 30U)) & S_SALT1];
            aOrbiterH = (((aWandererJ + RotL64(aPrevious, 5U)) + RotL64(aCarry, 23U)) + 0x69983594C0AB6863ULL) + aOASaltC[(((511U - aIndex) + 449U)) & S_SALT1];
            aOrbiterI = (aWandererE + RotL64(aIngress, 21U)) + 0xF0D4D29B9E4739D8ULL;
            aOrbiterG = ((aWandererB + RotL64(aScatter, 35U)) + 0xBEE28342557A460CULL) + aOASaltE[((aIndex + 482U)) & S_SALT1];
            aOrbiterE = ((aWandererK + RotL64(aPrevious, 11U)) + 0x50DD47D9D28D381DULL) + aOASaltG[(((511U - aIndex) + 465U)) & S_SALT1];
            aOrbiterB = (((aWandererI + RotL64(aIngress, 29U)) + RotL64(aCarry, 43U)) + 0x36D74385BD90A3C6ULL) + aOASaltB[((aIndex + 471U)) & S_SALT1];
            aOrbiterC = (aWandererC + RotL64(aScatter, 58U)) + 0x8A9A84189306D4E3ULL;
            //
            aOrbiterA = (aOrbiterA + aOrbiterH) + 0xD92AA8C9C1A092C3ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterA) ^ 0x7068702A5BB294D0ULL) ^ aOUSaltB[(((511U - aIndex) + 392U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x4A68E872FE492579ULL), 47U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0x93718303319D3114ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterH) ^ 0x5B4CEB8EE3BDE6EAULL;
            aOrbiterE = RotL64((aOrbiterE * 0x8BCF09FDAACFD2E3ULL), 57U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x5EBB858CDE5C3CF7ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0xA72C662EB8641E22ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xBED92FEC5F362EB5ULL), 29U);
