            //
            aIngress = (RotL64(aIceLaneD[((aIndex + 3471U)) & S_BLOCK1], 24U) ^ RotL64(aIceLaneB[((aIndex + 7565U)) & S_BLOCK1], 13U));
            aIngress ^= (RotL64(aHeartLaneB[((aIndex + 5343U)) & S_BLOCK1], 39U) ^ RotL64(aSoilLaneD[((aIndex + 5151U)) & S_BLOCK1], 47U));
