            //
            aScatter = (RotL64(aCross, 37U) ^ RotL64(aPrevious, 23U)) ^ (RotL64(aCarry, 50U) + RotL64(aIngress, 3U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterI = ((aWandererC + RotL64(aPrevious, 57U)) + 0x05CFBA2DDFDA13E4ULL) + aOASaltC[(((511U - aIndex) + 425U)) & S_SALT1];
            aOrbiterG = ((aWandererH + RotL64(aScatter, 13U)) + 0xA306931618D57D19ULL) + aOASaltA[(((511U - aIndex) + 290U)) & S_SALT1];
            aOrbiterF = (aWandererG + RotL64(aCross, 28U)) + 0xB15E78E7A1DDD956ULL;
            aOrbiterA = ((aWandererF + RotL64(aIngress, 3U)) + RotL64(aCarry, 53U)) + 0x4087B6D4C86E9C1DULL;
