            aWandererE = aWandererE ^ ((RotL64(aPrevious, 35U) + RotL64(aOrbiterE, 53U)) + aOrbiterJ);
            aWandererJ = aWandererJ + (((RotL64(aScatter, 47U) + RotL64(aOrbiterJ, 43U)) + aOrbiterD) + aWUSaltB[(((511U - aIndex) + 221U)) & S_SALT1]);
            aWandererA = aWandererA ^ (((RotL64(aPrevious, 60U) + aOrbiterC) + RotL64(aOrbiterJ, 39U)) + aWUSaltD[((aIndex + 4U)) & S_SALT1]);
            //
