            aOrbiterF = (aWandererF + RotL64(aPrevious, 34U)) + 0x1312B536858DF0EAULL;
            aOrbiterH = (aWandererI + RotL64(aScatter, 53U)) + 0xD56E9A4592F9A554ULL;
            aOrbiterG = (aWandererK + RotL64(aPrevious, 19U)) + 0x7912231B5563FB92ULL;
            aOrbiterA = (aWandererB + RotL64(aIngress, 43U)) + 0x50AAB830661E0E9EULL;
            aOrbiterI = (((aWandererC + RotL64(aCross, 11U)) + RotL64(aCarry, 35U)) + 0x9F890711E2DCD813ULL) + aOASaltD[(((511U - aIndex) + 323U)) & S_SALT1];
            aOrbiterB = (((aWandererE + RotL64(aScatter, 47U)) + RotL64(aCarry, 53U)) + 0x9A9B2081BEC76922ULL) + aOASaltE[(((511U - aIndex) + 159U)) & S_SALT1];
            aOrbiterC = (((aWandererG + RotL64(aPrevious, 13U)) + RotL64(aCarry, 21U)) + 0x0B4B92E5A0BDD113ULL) + aOASaltB[((aIndex + 209U)) & S_SALT1];
            aOrbiterK = (aWandererJ + RotL64(aScatter, 21U)) + 0xBEC96C102B6840E6ULL;
            aOrbiterD = (aWandererD + RotL64(aCross, 30U)) + 0x55EEC5102CD51FADULL;
            //
            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0xC4B1EF9306B3EB57ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterE) ^ 0x89A1DB7B0CFBB6A7ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x79465C0FC3953A03ULL), 21U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0xCE8F65398CB69EFCULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0x1502DB1AE0BDADCAULL;
            aOrbiterA = RotL64((aOrbiterA * 0x0B3A1F96A2205F0FULL), 3U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0xF777644858B33055ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterI) ^ 0xC0C14EE92943E349ULL;
