            //
            aWandererG = aWandererG + ((RotL64(aCross, 13U) + RotL64(aOrbiterJ, 27U)) + aOrbiterH);
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 51U) + aOrbiterA) + RotL64(aOrbiterI, 37U));
