            aWandererH = aWandererH + (((RotL64(aCross, 5U) + RotL64(aOrbiterC, 14U)) + aOrbiterI) + RotL64(aCarry, 11U));
            aWandererE = aWandererE ^ ((RotL64(aScatter, 26U) + aOrbiterB) + RotL64(aOrbiterK, 19U));
            aWandererC = aWandererC + (((RotL64(aPrevious, 19U) + aOrbiterF) + RotL64(aOrbiterG, 11U)) + RotL64(aCarry, 21U));
            //
            aCarry = aCarry + (aWandererA ^ RotL64(aWandererF, 46U));
