            aOrbiterG = (aWandererB + RotL64(aScatter, 27U)) + 0x5B9130DA3234CE2BULL;
            aOrbiterA = ((aWandererD + RotL64(aPrevious, 13U)) + 0xA30155412CCFC09CULL) + aOASaltD[((aIndex + 143U)) & S_SALT1];
            aOrbiterD = ((aWandererE + RotL64(aIngress, 35U)) + 0x96EC9F9A91A5E224ULL) + aOASaltH[((aIndex + 367U)) & S_SALT1];
            aOrbiterF = (((aWandererI + RotL64(aPrevious, 43U)) + RotL64(aCarry, 5U)) + 0xA3965D1787D8BF17ULL) + aOASaltC[(((511U - aIndex) + 221U)) & S_SALT1];
