            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aIngress, 13U) + RotL64(aCarry, 56U)) + (RotL64(aPrevious, 29U) ^ RotL64(aCross, 41U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterC = (aWandererE + RotL64(aIngress, 47U)) + 0x2287428C7B4A6C25ULL;
            aOrbiterE = ((aWandererG + RotL64(aPrevious, 54U)) + 0x2C2856E4C986D317ULL) + aOASaltG[((aIndex + 87U)) & S_SALT1];
            aOrbiterG = (((aWandererH + RotL64(aScatter, 35U)) + RotL64(aCarry, 23U)) + 0x184AF51AE2336BECULL) + aOASaltB[(((511U - aIndex) + 415U)) & S_SALT1];
            aOrbiterI = ((aWandererB + RotL64(aCross, 41U)) + 0x84647B993CBCB8F2ULL) + aOASaltE[((aIndex + 397U)) & S_SALT1];
            aOrbiterA = ((aWandererF + RotL64(aIngress, 19U)) + RotL64(aCarry, 57U)) + 0x7E42559B29D46461ULL;
            aOrbiterK = ((aWandererJ + RotL64(aPrevious, 11U)) + RotL64(aCarry, 35U)) + 0xDF4352E3B1AAC25EULL;
            aOrbiterH = (aWandererD + RotL64(aCross, 29U)) + 0xA154980B5DB0D2A0ULL;
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0x7C8E07EAC98C35E8ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0x6A668B0C059793EAULL;
