            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0x8569F9545DE191AAULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterI) ^ 0x51D50630D6C63DACULL;
            aOrbiterE = RotL64((aOrbiterE * 0x4190EEE9306ADD5DULL), 23U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterC) + 0x3B4746D117385199ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterA) ^ 0xF4A65CE3886170DBULL;
            aOrbiterK = RotL64((aOrbiterK * 0xBD1604C8F2299179ULL), 5U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterK) + 0x2664DF2BBEED39BDULL) + aOUSaltB[((aIndex + 38U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterE) ^ 0x3E2CC25D89DC0A0AULL) ^ aOUSaltH[((aIndex + 449U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xB09526C0F2505ECFULL), 51U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0x0BE3B2634D4CAF1BULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0x49F39E039DE94093ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x80EF9146DD5E79F1ULL), 29U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterI) + 0x049E92B6734ECDCFULL) + aOUSaltF[((aIndex + 201U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0xBDC8DAAF87CA9F9AULL;
            aOrbiterC = RotL64((aOrbiterC * 0xFCBE31E934F8D8D9ULL), 57U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0xC1F983A699F107B2ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterG) ^ 0x43712A79E6D83184ULL) ^ aOUSaltC[(((511U - aIndex) + 281U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xAF38B7B41F1BBBADULL), 13U);
            //
            aIngress = aOrbiterA ^ RotL64(aOrbiterH, 13U);
            aIngress = aIngress + (aOrbiterC ^ RotL64(aOrbiterG, 3U));
