            aOrbiterI = ((aWandererD + RotL64(aPrevious, 19U)) + RotL64(aCarry, 21U)) + 0xCB38AF1AF0FC8D4AULL;
            aOrbiterE = ((aWandererG + RotL64(aScatter, 53U)) + RotL64(aCarry, 5U)) + 0x0F0305A3E5E70887ULL;
