            aOrbiterD = RotL64((aOrbiterD * 0xA71B65F3552AE2D5ULL), 43U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterB) + 0x0885ED01CA3CCC6DULL) + aOUSaltE[(((511U - aIndex) + 320U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterC) ^ 0x54248F6F1B7A52D3ULL) ^ aOUSaltH[((aIndex + 84U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xDAC34C6DA4B79B39ULL), 57U);
