            aWandererH = aWandererH ^ ((RotL64(aCross, 39U) + aOrbiterH) + RotL64(aOrbiterD, 43U));
            aWandererG = aWandererG + (((RotL64(aPrevious, 34U) + aOrbiterB) + RotL64(aOrbiterC, 47U)) + RotL64(aCarry, 21U));
            aWandererA = aWandererA ^ (((RotL64(aIngress, 3U) + RotL64(aOrbiterH, 51U)) + aOrbiterK) + aWUSaltH[(((511U - aIndex) + 44U)) & S_SALT1]);
