            aWandererC = aWandererC ^ (((RotL64(aPrevious, 13U) + aOrbiterJ) + RotL64(aOrbiterK, 21U)) + aWUSaltF[((aIndex + 295U)) & S_SALT1]);
            aWandererK = aWandererK + (((RotL64(aIngress, 39U) + RotL64(aOrbiterJ, 47U)) + aOrbiterI) + aWUSaltD[((aIndex + 287U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aCross, 27U) + aOrbiterG) + RotL64(aOrbiterE, 34U));
            aWandererG = aWandererG + ((RotL64(aScatter, 10U) + aOrbiterH) + RotL64(aOrbiterC, 5U));
            //
            aCarry = aCarry + (RotL64(aWandererB, 3U) ^ aWandererK);
