            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterG = ((aWandererJ + RotL64(aScatter, 39U)) + 0xDE8F215EB80B8ADAULL) + aOASaltF[(((511U - aIndex) + 391U)) & S_SALT1];
            aOrbiterE = ((aWandererH + RotL64(aPrevious, 57U)) + RotL64(aCarry, 29U)) + 0xE7A6376FB79BBB1CULL;
            aOrbiterC = ((aWandererD + RotL64(aCross, 36U)) + 0x80D5D3470755B310ULL) + aOASaltD[((aIndex + 334U)) & S_SALT1];
            aOrbiterK = (aWandererF + RotL64(aIngress, 3U)) + 0x24D66412CC8B4138ULL;
            aOrbiterB = (((aWandererA + RotL64(aScatter, 19U)) + RotL64(aCarry, 41U)) + 0xDCEBAF99CCCFD99AULL) + aOASaltH[(((511U - aIndex) + 79U)) & S_SALT1];
            aOrbiterF = (aWandererG + RotL64(aIngress, 21U)) + 0x0179C287AF679F17ULL;
            aOrbiterA = ((aWandererB + RotL64(aPrevious, 43U)) + 0xFBA8434DD3B11ADBULL) + aOASaltC[(((511U - aIndex) + 328U)) & S_SALT1];
